record.field:
{
    "name": "create_lead",
    "description": "Create a new lead/opportunity in CRM",
    "parameters": {
        "type": "object",
        "properties": {
            "name": {
                "type": "string",
                "description": "Lead title or opportunity name"
            },
            "contact_name": {
                "type": "string",
                "description": "Contact person name"
            },
            "email": {
                "type": "string",
                "description": "Email address"
            },
            "phone": {
                "type": "string",
                "description": "Phone number"
            },
            "description": {
                "type": "string",
                "description": "Additional notes or requirements"
            }
        },
        "required": ["name"]
    }
}
